/* eslint-disable space-in-parens */

import AccessorArray = require( '@stdlib/array/base/accessor' );
import gleslie = require( './index' );


// TESTS //

// The function returns a collection...
{
	const f = new Float64Array( 3 );
	const s = new Float64Array( 2 );
	const out = new Float64Array( 9 );

	gleslie( 'row-major', 3, f, 1, s, 1, out, 3 ); // $ExpectType Float64Array
	gleslie( 'row-major', 3, new AccessorArray( f ), 1, new AccessorArray( s ), 1, new AccessorArray( out ), 3 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const f = new Float64Array( 3 );
	const s = new Float64Array( 2 );
	const out = new Float64Array( 9 );

	gleslie( 10, 3, f, 1, s, 1, out, 3 ); // $ExpectError
	gleslie( true, 3, f, 1, s, 1, out, 3 ); // $ExpectError
	gleslie( false, 3, f, 1, s, 1, out, 3 ); // $ExpectError
	gleslie( null, 3, f, 1, s, 1, out, 3 ); // $ExpectError
	gleslie( undefined, 3, f, 1, s, 1, out, 3 ); // $ExpectError
	gleslie( [], 3, f, 1, s, 1, out, 3 ); // $ExpectError
	gleslie( {}, 3, f, 1, s, 1, out, 3 ); // $ExpectError
	gleslie( ( x: number ): number => x, 3, f, 1, s, 1, out, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
