// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const f = new Float64Array( 3 );
	const s = new Float64Array( 2 );
	const out = new Float64Array( 9 );

	gleslie(); // $ExpectError
	gleslie( 'row-major' ); // $ExpectError
	gleslie( 'row-major', 3 ); // $ExpectError
	gleslie( 'row-major', 3, f ); // $ExpectError
	gleslie( 'row-major', 3, f, 1 ); // $ExpectError
	gleslie( 'row-major', 3, f, 1, s ); // $ExpectError
	gleslie( 'row-major', 3, f, 1, s, 1 ); // $ExpectError
	gleslie( 'row-major', 3, f, 1, s, 1, out ); // $ExpectError
	gleslie( 'row-major', 3, f, 1, s, 1, out, 3, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a collection...
{
	const f = new Float64Array( 3 );
	const s = new Float64Array( 2 );
	const out = new Float64Array( 9 );

	gleslie.ndarray( 3, f, 1, 0, s, 1, 0, out, 3, 1, 0 ); // $ExpectType Float64Array
	gleslie.ndarray( 3, new AccessorArray( f ), 1, 0, new AccessorArray( s ), 1, 0, new AccessorArray( out ), 3, 1, 0 ); // $ExpectType AccessorArray<number>
}

